window.__finlexDocLoaded(10038,{"id":10038,"articles":[{"id":1000095,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Deals with the external auditor's responsibilities if using the work of internal auditors, including obtaining audit evidence and direct assistance.","seq":0},{"id":1000096,"no":"ISA 610.15–35","heading":"Using the Work of Internal Auditors","text":"Evaluate internal audit objectivity, competence, and systematic/disciplined approach before using its work; external auditor remains solely responsible for the audit opinion and cannot use direct assistance where prohibited by law/regulation.","seq":1},{"id":1000097,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 1 (ISQM 1–2, ISA 200–720)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
